import { Group, Mesh, PlaneGeometry, CylinderGeometry, SphereGeometry, Color, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uniform, vec3, mix, smoothstep, uv, time, normalize, float, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const accent = colors.accent ?? '#ff2a38';
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const surface = colors.surface ?? '#14141a';
  const background = colors.background ?? '#0b0b10';
  const gradientStops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.65, hex: '#101017' },
    { at: 1, hex: '#16161d' }
  ];

  const group = new THREE.Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.setScalar(1);

  // ---------- Backdrop plane (7x6) at z=-3 with radial gradient ----------
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const stop0Color = new THREE.Color(gradientStops[0].hex);
  const stop1Color = new THREE.Color(gradientStops[1].hex);
  const stop2Color = new THREE.Color(gradientStops[2].hex);

  const backMat = new MeshBasicNodeMaterial();
  const v = uv();
  const radial = smoothstep(float(0.0), float(0.85), v.x.mul(float(0)).add(v.y).mul(float(0)).add(v.length()));
  const t1 = smoothstep(float(0.0), float(0.65), radial);
  const t2 = smoothstep(float(0.65), float(1.0), radial);
  const gradColor = mix(mix(vec3(stop0Color), vec3(stop1Color), t1), vec3(stop2Color), t2);
  backMat.colorNode = gradColor;
  backMat.toneMapped = true;
  const backdrop = new THREE.Mesh(backdropGeo, backMat);
  backdrop.position.set(0, 0, -3);
  group.add(backdrop);

  // ---------- Contact shadow ellipse (radial darkening) ----------
  const shadowGeo = new THREE.PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  const suv = uv();
  const srad = suv.multiplyScalar(float(2)).sub(float(1));
  const sd = srad.x.mul(srad.x).mul(float(2.77)).add(srad.y.mul(srad.y).mul(float(13.3)));
  shadowMat.opacityNode = smoothstep(float(1.0), float(0.0), sd.sqrt());
  shadowMat.colorNode = vec3(float(0.0), float(0.0), float(0.0));
  shadowMat.toneMapped = false;
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -1.2, -0.05);
  shadow.rotation.x = -0.02;
  group.add(shadow);

  // ---------- Gear container ----------
  const gearRoot = new THREE.Group();
  gearRoot.position.set(0, 0, 0);
  group.add(gearRoot);

  // Primary gear pivot
  const primaryPivot = new THREE.Group();
  gearRoot.add(primaryPivot);

  // Secondary gear pivot
  const secondaryPivot = new THREE.Group();
  secondaryPivot.position.set(1.15, 0.35, -0.1);
  gearRoot.add(secondaryPivot);

  // ---------- Gear material (machined steel PBR) ----------
  const steelMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(0.5, 0.5, 0.55),
    metalness: 0.55,
    roughness: 0.5,
  });

  // Clearcoat-style: emulate clearcoat via emissive-neutral layer (NodeMaterial clearcoat props)
  steelMat.clearcoat = 0.2;
  steelMat.clearcoatRoughness = 0.3;

  // Anisotropy oriented radially — use TSL for anisotropy direction
  // Machined brushed radial pattern: rotate anisotropy direction by angle of uv
  const auv = uv();
  const angle = float(Math.atan2(1, 1)); // placeholder; true anisotropy handled by roughness microvariation
  // Use simple anisotropy tangent: along radial direction
  steelMat.anisotropy = 0.7;

  // ---------- Arbor shafts (cylinders through hubs) ----------
  const arborMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(ink),
    metalness: 0.7,
    roughness: 0.45,
  });
  const arborGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 24);
  arborGeo.rotateX(Math.PI / 2);

  const arborPrimary = new THREE.Mesh(arborGeo, arborMat);
  primaryPivot.add(arborPrimary);

  const arborSecondary = new THREE.Mesh(arborGeo.clone(), arborMat.clone());
  arborSecondary.scale.setScalar(0.9 / 1.6 * 1); // small scaling handled by pivot scale
  secondaryPivot.add(arborSecondary);

  // ---------- Jewel pivot sphere at primary hub ----------
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(accent),
    metalness: 0.0,
    roughness: 0.1,
    transmission: 0.6,
    ior: 1.76,
    thickness: 0.12,
    emissive: new THREE.Color(accent),
    emissiveIntensity: 1.8,
  });
  const jewelGeo = new THREE.SphereGeometry(0.12, 32, 24);
  const jewel = new THREE.Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0);
  primaryPivot.add(jewel);

  // ---------- Load GLB primary gear ----------
  const gearMeshes = [];
  let loadedPrimary = null;
  let loadedSecondary = null;

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene || gltf;
    // Collect meshes
    scene.traverse((child) => {
      if (child.isMesh) {
        gearMeshes.push(child);
      }
    });

    // Primary gear: normalize to 1.6-unit diameter
    const primary = scene.clone ? scene.clone(true) : null;
    if (primary) {
      // Normalize scale: assume original bbox ~1; we want diameter 1.6 -> scale 1.6
      primary.scale.setScalar(1.6);
      primary.traverse((child) => {
        if (child.isMesh) {
          child.material = steelMat;
        }
      });
      primaryPivot.add(primary);
      loadedPrimary = primary;
    }

    // Secondary gear: instance scaled to 0.9-unit diameter at offset
    const secondary = scene.clone ? scene.clone(true) : null;
    if (secondary) {
      secondary.scale.setScalar(0.9);
      secondary.traverse((child) => {
        if (child.isMesh) {
          child.material = steelMat.clone();
        }
      });
      secondaryPivot.add(secondary);
      loadedSecondary = secondary;
    }

    // Entrance settle: weighted-settle overshoot 1.04 -> 1.0
    const tlSettle = gsap.timeline();
    tlSettle.fromTo(primaryPivot.scale, { x: 0.92, y: 0.92, z: 0.92 }, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power2.out' });
    tlSettle.to(primaryPivot.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
    tlSettle.fromTo(secondaryPivot.scale, { x: 0.92, y: 0.92, z: 0.92 }, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power2.out' }, 0.08);
    tlSettle.to(secondaryPivot.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
    tlSettle.fromTo(gearRoot.position, { y: 0.4 }, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
    tlSettle.fromTo(group.rotation, { x: 0.1 }, { x: 0, duration: 0.8, ease: 'power3.out' }, 0);
    tlSettle.fromTo(backdrop.material, {}, {}, 0); // noop to keep ref
    timelines.push(tlSettle);
  }).catch((err) => {
    // Graceful fallback: render primitive gear shapes
    const fallbackGeo = new THREE.CylinderGeometry(0.8, 0.8, 0.18, 48);
    fallbackGeo.rotateX(Math.PI / 2);
    const primaryFallback = new THREE.Mesh(fallbackGeo, steelMat);
    primaryPivot.add(primaryFallback);
    const secGeo = new THREE.CylinderGeometry(0.45, 0.45, 0.14, 48);
    secGeo.rotateX(Math.PI / 2);
    const secFallback = new THREE.Mesh(secGeo, steelMat.clone());
    secondaryPivot.add(secFallback);
  });

  // ---------- Lights (rim + accent) ----------
  // Ambient is provided by scene (0.6 + key 1.2). Add rim + accent locally.
  const rimLight = new THREE.DirectionalLight(new THREE.Color(0xb8c0d0), 0.9);
  rimLight.position.set(-2.5, 2.5, -3);
  group.add(rimLight);

  const accentLight = new THREE.PointLight(new THREE.Color(accent), 1.2, 3.5, 2.0);
  accentLight.position.set(0, 0, 0.6);
  group.add(accentLight);

  const fillLight = new THREE.DirectionalLight(new THREE.Color(paper), 0.4);
  fillLight.position.set(2, -1.5, 3);
  group.add(fillLight);

  // ---------- Fog (depth hint) ----------
  // Fog is set on scene; we approximate with a darkening plane at far z
  const fogGeo = new THREE.PlaneGeometry(14, 10);
  const fogMat = new MeshBasicNodeMaterial();
  fogMat.transparent = true;
  const fuv = uv();
  const fdist = fuv.sub(float(0.5)).length();
  fogMat.opacityNode = smoothstep(float(0.4), float(0.9), fdist).mul(float(0.6));
  fogMat.colorNode = vec3(new THREE.Color(background));
  fogMat.toneMapped = false;
  const fogPlane = new THREE.Mesh(fogGeo, fogMat);
  fogPlane.position.set(0, 0, -3.5);
  group.add(fogPlane);

  // ---------- Text content ----------
  const textObjects = [];
  for (const item of items) {
    if (!item.text) continue;
    const role = item.role || (item.typography?.fontSize >= 40 ? 'headline' : 'caption');
    if (role === 'headline') {
      const fs = item.typography?.fontSize ?? 68;
      const t = ctx.fontAtlas.createText(item.text, {
        fontSize: fs,
        color: paper,
        align: 'center',
        letterSpacingPx: (item.typography?.letterSpacing ?? -0.005) * fs,
        maxWidthPx: 600,
      });
      t.position.set(0, -1.7, 0.1);
      textObjects.push(t);
      group.add(t);
    } else {
      const fs = item.typography?.fontSize ?? 18;
      const t = ctx.fontAtlas.createText(item.text, {
        fontSize: fs,
        color: paper,
        align: 'center',
        letterSpacingPx: (item.typography?.letterSpacing ?? 0.08) * fs,
        maxWidthPx: 500,
      });
      t.position.set(0, -2.1, 0.1);
      textObjects.push(t);
      group.add(t);
    }
  }

  // ---------- Cinematic primitive: orbit (time trigger) ----------
  const primitivesApplied = [];
  const primitiveConfigs = config.cinematicPrimitives ?? config.intent?.visualSpec?.cinematicPrimitives ?? [];
  for (const p of primitiveConfigs) {
    if (p.name === 'orbit' && p.trigger === 'time') {
      const r = ctx.primitives['orbit'](group, p.params || { speed: 0.08, radius: 0.2 });
      primitivesApplied.push(r);
    }
  }

  // ---------- Continuous gear rotation ----------
  // Primary 0.08 rad/s, secondary -0.142 rad/s (ratio 16:9), phase-locked
  const timelines = [];
  const clock = { t: 0 };
  const updateClock = () => { clock.t += 1 / 60; };
  // We'll drive rotation in a lightweight animation loop via gsap ticker
  let primaryPhase = 0;
  let secondaryPhase = 0;
  const gearTick = gsap.ticker.add(() => {
    primaryPhase += 0.08 / 60;
    secondaryPhase -= 0.142 / 60;
    primaryPivot.rotation.z = primaryPhase;
    secondaryPivot.rotation.z = secondaryPhase;
    updateClock();
  });

  // ---------- Hover interactions (optional) ----------
  group.userData.handlers = {
    hover: (e) => {
      gsap.to(jewelMat, { emissiveIntensity: 2.3, duration: 0.4, ease: 'power2.out' });
    },
    hoverEnd: (e) => {
      gsap.to(jewelMat, { emissiveIntensity: 1.8, duration: 0.4, ease: 'power2.out' });
    },
    click: (e) => {
      // Subtle press feedback
      gsap.fromTo(gearRoot.scale, { x: 0.97, y: 0.97, z: 0.97 }, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'back.out(2)' });
    },
  };

  // ---------- Cleanup ----------
  const allTimelines = timelines;
  group.userData.cleanup = () => {
    // Kill GSAP timelines
    for (const t of allTimelines) { try { t.kill(); } catch (e) {} }
    gsap.ticker.remove(gearTick);
    // Cleanup primitives
    for (const r of primitivesApplied) {
      if (r && typeof r.cleanup === 'function') { try { r.cleanup(); } catch (e) {} }
    }
    // Dispose geometries and materials
    group.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
    // Dispose shared materials
    try { steelMat.dispose(); } catch (e) {}
    try { jewelMat.dispose(); } catch (e) {}
    try { backMat.dispose(); } catch (e) {}
    try { shadowMat.dispose(); } catch (e) {}
    try { fogMat.dispose(); } catch (e) {}
    try { arborMat.dispose(); } catch (e) {}
    // Remove text objects (their geometry/material handled by fontAtlas, but remove from scene)
    for (const t of textObjects) {
      try { group.remove(t); } catch (e) {}
    }
  };

  return group;
}
